"""Regenerate BitLocker test vectors independently with Python cryptography.

Requires cryptography 48.0.0. Produces crypto vectors, not Windows qualification.
Run from the repository root; the Rust tests need no Python dependencies.
"""
from hashlib import sha256
from pathlib import Path
from struct import pack

from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.ciphers.aead import AESCCM


def wrapped(key, secret, method, nonce_byte):
    record = pack("<IHHI", len(secret) + 12, 1, 0, method) + secret
    nonce = bytes([nonce_byte]) * 12
    sealed = AESCCM(key, tag_length=16).encrypt(nonce, record, None)
    return nonce + sealed[-16:] + sealed[:-16]


salt = bytes(range(16, 32))
words = b"".join(pack("<H", 10000 + i) for i in range(8))
initial = sha256(words).digest()
last = bytes(32)
for count in range(1048576):
    last = sha256(last + initial + salt + pack("<Q", count)).digest()

vmk = bytes(range(160, 192))
clear = bytes(range(64, 96))
vectors = {
    "RECOVERY_VMK": wrapped(last, vmk, 0x2003, 1),
    "CLEAR_VMK": wrapped(clear, vmk, 0x2003, 2),
}
for method, keylen in [(0x8004, 32), (0x8005, 64)]:
    key = bytes(range(keylen))
    label = "XTS128" if keylen == 32 else "XTS256"
    vectors[label + "_FVEK"] = wrapped(vmk, key, method, 3)
    for sector_size in [512, 4096]:
        for offset, kind in [(0x40000, "BOOT"), (0x2000, "DATA")]:
            plaintext = bytes((i * 7 + 3) % 256 for i in range(sector_size))
            if kind == "BOOT":
                plaintext = bytearray(plaintext)
                plaintext[3:11] = b"NTFS    "
                plaintext[11:13] = pack("<H", sector_size)
                plaintext[510:512] = b"\x55\xaa"
                plaintext = bytes(plaintext)
            tweak = (offset // sector_size).to_bytes(16, "little")
            encryptor = Cipher(algorithms.AES(key), modes.XTS(tweak)).encryptor()
            vectors[f"{label}_{sector_size}_{kind}"] = (
                encryptor.update(plaintext) + encryptor.finalize()
            )

lines = [
    "// Generated by generate_bitlocker_vectors.py using cryptography 48.0.0.",
    "// Independent AES-CCM, SHA-256 derivation, and physical-sector XTS vectors.",
]
for name, value in vectors.items():
    chunks = [value.hex()[i:i + 96] for i in range(0, len(value.hex()), 96)]
    lines.append(f'pub const {name}: &str = concat!(')
    lines.extend(f'    "{chunk}",' for chunk in chunks)
    lines.append(");")
Path("tests/fixtures/bitlocker_vectors.rs").write_text("\n".join(lines) + "\n")
